import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, posix, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { designDocuments } from './design-documents.ts';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const output = resolve(root, 'apps/docs/src/routes/design');
const generatedNotice =
  '<!-- Generated by scripts/sync-design-docs.ts. Edit the source in docs/. -->';

function mapProse(source: string, transform: (line: string) => string): string {
  let fence: { marker: string; length: number } | undefined;
  return source
    .replace(/\r\n/g, '\n')
    .split('\n')
    .map((line) => {
      const marker = /^\s{0,3}(`{3,}|~{3,})/.exec(line)?.[1];
      if (marker) {
        if (!fence) fence = { marker: marker[0], length: marker.length };
        else if (marker[0] === fence.marker && marker.length >= fence.length)
          fence = undefined;
        return line;
      }
      if (fence) return line;
      return transform(line);
    })
    .join('\n');
}

/** Rewrite document links in prose, leaving fenced and inline examples intact. */
export function rewriteDocumentLinks(source: string, slug: string): string {
  return mapProse(source, (line) =>
    line
      .split(/(`+[^`]*`+)/g)
      .map((part, index) => {
        if (index % 2) return part;
        return part.replace(
          /\]\((?:\.\/)?([^\s)]+\.md)(#[^\s)]*)?\)/g,
          (link, filename: string, hash: string = '') => {
            const doc = designDocuments.find(
              (entry) => entry.source === filename
            );
            if (!doc) throw new Error(`Unpublished document link: ${filename}`);
            const relative = posix.relative(slug, doc.slug) || '.';
            return `](${relative}/${hash})`;
          }
        );
      })
      .join('')
  );
}

/** SveltePress uses template literals for inline code; render examples as literal text. */
export function protectExamples(source: string): string {
  const escape = (text: string): string =>
    text
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('{', '&#123;')
      .replaceAll('}', '&#125;');
  return mapProse(source, (line) =>
    line
      .split(/(`+[^`]*`+)/g)
      .map((part, index) =>
        index % 2
          ? `<code>${escape(part.replace(/^`+|`+$/g, ''))}</code>`
          : part.replaceAll('{', '&#123;').replaceAll('}', '&#125;')
      )
      .join('')
  );
}

function frontmatter(title: string, description: string): string {
  return `---\ntitle: ${JSON.stringify(title)}\ndescription: ${JSON.stringify(description)}\n---\n\n${generatedNotice}\n\n`;
}

async function writePage(slug: string, content: string): Promise<void> {
  const destination = resolve(output, slug, '+page.md');
  await mkdir(dirname(destination), { recursive: true });
  if ((await readFile(destination, 'utf8').catch(() => '')) !== content) {
    await writeFile(destination, content);
  }
}

export async function syncDesignDocs(): Promise<void> {
  for (const doc of designDocuments) {
    const source = await readFile(resolve(root, 'docs', doc.source), 'utf8');
    await writePage(
      doc.slug,
      frontmatter(doc.title, doc.description) +
        protectExamples(rewriteDocumentLinks(source, doc.slug))
    );
  }
  const list = (archived: boolean): string =>
    designDocuments
      .filter((doc) => doc.archived === archived)
      .map(
        (doc) =>
          `- [${doc.title}](./${doc.slug}/) — **${doc.status}**. ${doc.description}`
      )
      .join('\n');
  await writePage(
    '',
    frontmatter(
      'Design documents',
      'Product specifications and development proposals for the CII design system.'
    ) +
      `# Design documents\n\nThese documents describe product requirements and proposed implementation work. Draft plans describe intended behaviour; the component documentation records what is currently available.\n\n## Current documents\n\n${list(false)}\n\n## Archive\n\n${list(true)}\n\nThe mapping development plan supersedes the earlier mapping specification. Where they disagree, the development plan takes precedence.\n`
  );
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  await syncDesignDocs();
}
